def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 7]
    if len(pts) >= 2:
        dr, dc = pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]
        r, c = pts[-1]
        while 0 <= r + dr < len(out) and 0 <= c + dc < len(out[0]):
            r, c = r + dr, c + dc
            if out[r][c] != 1:
                break
            out[r][c] = 7
    return out

