def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 7]
    if len(pts) >= 2:
        dr, dc = pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]
        # The 7 pair gives a diagonal vector. Continue that vector from
