        r, c = pts[0]
        while 0 <= r + dr < len(out) and 0 <= c + dc < len(out[0]):
            r, c = r + dr, c + dc
            if out[r][c] == 3:
                break
            if out[r][c] == 1:
                out[r][c] = 7
    return out

