    (r0, c0), (r1, c1) = pts[0], pts[1]
    dr, dc = r1-r0, c1-c0
    # In the second demo the 4s form the moving diagonal; extend that color.
    four = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 4]
    if four:
        r,c = four[-1]
